/** Exact Source205 descriptors; no observations/caller authority. */
import assert from 'node:assert/strict';import{gunzipSync}from'node:zlib';import{createHash}from'node:crypto';
const raw=gunzipSync(Buffer.from('','base64'),{maxOutputLength:20634544});
assert.equal(raw.length,20634544);assert.equal(createHash('sha256').update(raw).digest('hex'),'78323f50ec9b494193ec97bcf43d53c424c6d68432a8975aadc912f67e66ffe4');
const freeze=x=>{if(x&&typeof x==='object'){for(const v of Object.values(x))freeze(v);Object.freeze(x);}return x;};
export const HEADER205_SOURCE_CONTRACT=freeze(JSON.parse(raw.toString('utf8')));
